package com.rulecraft.decisionops.deployment.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="runtime_deployment")
public class RuntimeDeployment {@Id private UUID id;@Column(name="tenant_id",nullable=false)private UUID tenantId;@Column(name="project_id",nullable=false)private UUID projectId;@Column(name="decision_service_id",nullable=false)private UUID serviceId;@Column(name="environment_id",nullable=false)private UUID environmentId;@Column(name="decision_version_id",nullable=false)private UUID decisionVersionId;@Column(name="change_request_id",nullable=false)private UUID changeRequestId;@Column(name="client_request_id",nullable=false)private UUID clientRequestId;@Column(name="sequence_number",nullable=false)private int sequenceNumber;@Enumerated(EnumType.STRING)@Column(nullable=false,length=24)private RuntimeDeploymentState state;@Column(name="artifact_json",nullable=false,columnDefinition="text")private String artifactJson;@Column(name="artifact_fingerprint",nullable=false,length=64)private String artifactFingerprint;@Column(name="failure_code",length=80)private String failureCode;@Column(name="failure_detail",length=600)private String failureDetail;@Column(name="deployed_by",nullable=false)private UUID deployedBy;@Column(name="deployed_by_name",nullable=false,length=160)private String deployedByName;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version private long revision;protected RuntimeDeployment(){}public RuntimeDeployment(UUID tenantId,UUID projectId,UUID serviceId,UUID environmentId,UUID versionId,UUID requestId,UUID clientRequestId,int sequence,String artifact,String fingerprint,UUID actor,String actorName,Instant now){id=UUID.randomUUID();this.tenantId=tenantId;this.projectId=projectId;this.serviceId=serviceId;this.environmentId=environmentId;decisionVersionId=versionId;changeRequestId=requestId;this.clientRequestId=clientRequestId;sequenceNumber=sequence;state=RuntimeDeploymentState.CREATED;artifactJson=artifact;artifactFingerprint=fingerprint;deployedBy=actor;deployedByName=actorName;createdAt=updatedAt=now;}public RuntimeDeploymentState transition(RuntimeDeploymentState next,Instant now){var previous=state;state=next;updatedAt=now;return previous;}public void fail(String code,String detail,Instant now){state=RuntimeDeploymentState.FAILED;failureCode=code;failureDetail=detail;updatedAt=now;}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public UUID getProjectId(){return projectId;}public UUID getServiceId(){return serviceId;}public UUID getEnvironmentId(){return environmentId;}public UUID getDecisionVersionId(){return decisionVersionId;}public UUID getChangeRequestId(){return changeRequestId;}public UUID getClientRequestId(){return clientRequestId;}public int getSequenceNumber(){return sequenceNumber;}public RuntimeDeploymentState getState(){return state;}public String getArtifactJson(){return artifactJson;}public String getArtifactFingerprint(){return artifactFingerprint;}public String getFailureCode(){return failureCode;}public String getFailureDetail(){return failureDetail;}public String getDeployedByName(){return deployedByName;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public long getRevision(){return revision;}}
